  <style>
    :root{--bg:#f5f3ee;--ink:#171717;--muted:#68645d;--accent:#c88745;--dark:#1b1b19;--line:#ded9cf}
    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--bg);color:var(--ink);line-height:1.6}
    a{color:inherit;text-decoration:none}.wrap{width:min(1160px,92%);margin:auto}.nav{position:sticky;top:0;z-index:10;background:rgba(245,243,238,.94);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}.navin{height:76px;display:flex;align-items:center;justify-content:space-between}.logo{font-weight:900;letter-spacing:3px;font-size:22px}.links{display:flex;gap:28px;font-size:14px}.links a:hover{color:var(--accent)}
    .hero{padding:110px 0 100px;background:linear-gradient(120deg,#171714 0%,#29261f 65%,#4a3b2b 100%);color:#fff}.hero-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:60px;align-items:center}.eyebrow{font-size:13px;letter-spacing:3px;text-transform:uppercase;color:#d7a36b;font-weight:700}.hero h1{font-size:clamp(48px,7vw,88px);line-height:.96;margin:18px 0 25px;letter-spacing:-4px}.hero p{font-size:19px;color:#ddd7ce;max-width:620px}.btns{display:flex;gap:12px;margin-top:35px;flex-wrap:wrap}.btn{display:inline-block;padding:14px 22px;border:1px solid #fff;font-weight:700;font-size:14px}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.hero-card{min-height:390px;border:1px solid rgba(255,255,255,.22);display:flex;align-items:flex-end;padding:28px;background:linear-gradient(145deg,rgba(255,255,255,.12),rgba(255,255,255,.02));}.hero-card strong{font-size:30px;line-height:1.1}.section{padding:95px 0}.section-head{display:flex;justify-content:space-between;gap:30px;align-items:end;margin-bottom:45px}.section h2{font-size:clamp(35px,5vw,58px);line-height:1;margin:0;letter-spacing:-2px}.section-head p{max-width:430px;color:var(--muted);margin:0}.services{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}.service{background:var(--bg);padding:35px;min-height:240px}.num{color:var(--accent);font-weight:800}.service h3{font-size:24px;margin:35px 0 12px}.service p{color:var(--muted);margin:0}.portfolio{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.project{min-height:360px;background:#d6d0c5;position:relative;overflow:hidden}.project:nth-child(2){background:#b9b1a3}.project:nth-child(3){background:#c7b8a5}.project:nth-child(4){background:#a69e92}.project:nth-child(5){background:#d2c8ba}.project:nth-child(6){background:#b2aa9f}.project:after{content:'JET DESAIN';position:absolute;inset:auto 20px 18px;color:#fff;font-size:12px;letter-spacing:2px;font-weight:800}.project span{position:absolute;top:20px;left:20px;background:#fff;padding:7px 10px;font-size:11px;font-weight:700}.process{display:grid;grid-template-columns:repeat(4,1fr);gap:30px}.step{border-top:2px solid var(--ink);padding-top:18px}.step b{font-size:14px;color:var(--accent)}.step h3{font-size:21px}.step p{color:var(--muted);font-size:14px}.cta{background:var(--dark);color:#fff;padding:80px 0}.cta-in{display:flex;justify-content:space-between;align-items:center;gap:40px}.cta h2{font-size:clamp(34px,5vw,60px);line-height:1;margin:0}.cta p{color:#c9c5be}.footer{padding:28px 0;border-top:1px solid var(--line);font-size:13px;color:var(--muted);display:flex;justify-content:space-between}.mobile{display:none}
    @media(max-width:800px){.links{display:none}.mobile{display:block}.hero{padding:75px 0}.hero-grid{grid-template-columns:1fr}.hero-card{min-height:240px}.services,.portfolio{grid-template-columns:1fr}.process{grid-template-columns:1fr 1fr}.section{padding:70px 0}.section-head,.cta-in{display:block}.section-head p{margin-top:20px}.cta .btn{margin-top:30px}.footer{display:block}.footer span{display:block;margin-top:8px}}
  </style>
</head>
